$(()=>{$(document).on("click",".copy_to_clipboard_wrapper",e=>{let t=$(e.target);if(t.attr("class")=="copy_to_clipboard_wrapper"){t=t.find("*")}t.select();let o;try{o=document.execCommand("copy")}catch{o=false}t.blur();if(o){$(".copy_to_clipboard_wrapper.copied").removeClass("copied");t.parent(".copy_to_clipboard_wrapper").addClass("copied")}else{t.parent(".copy_to_clipboard_wrapper").addClass("copyfail")}});$(document).on("paste","input[type='text'][name='name']",e=>{e.preventDefault();const t=e.originalEvent.clipboardData||window.clipboardData;const o=t.getData("text");document.execCommand("insertText",false,o.trim())})});function copyTextToClipboard(e){const t=document.createElement("textarea");t.value=e;t.setAttribute("readonly","");t.style={position:"absolute",visibility:"hidden"};document.body.appendChild(t);t.select();document.execCommand("copy");document.body.removeChild(t)}